{"content": "1|// Token Radar's value model, radar-2. One snapshot in, one ranked board out.
2|//
3|// The board ranks every protocol that records no token (no market cap, no CoinGecko id, no symbol),
4|// and covers the whole watchlist plus the strongest pre-token protocols below its floor. Protocols
5|// whose token already trades are kept apart in a live set: the market prices them, so the model has
6|// nothing to say about them and never mixes them into the ranking.
7|//
8|// Implied value follows only from the snapshot's own figures, stated once here and echoed on the page:
9|//
10|//   implied = round( tvl_usd
11|//                    x category_multiple(category)      // what a dollar of TVL is worth to a token
12|//                    x (1 + clamp(change_7d, -60, +120)/100 x GROWTH_WEIGHT)   // momentum
13|//                    x (0.80 + 0.40 x min(age_days, 1095)/1095)                // runway without a token
14|//                  )
15|//
16|//   category_multiple: lending and CDP books are stickiest and carry the largest multiples (0.36);
17|//   perpetuals and DEX volume (0.32, 0.30) are strong but flow-driven; bridges and staking receipts
18|//   (0.18, 0.20) are thin-margin wrappers; CEX (0.05) is almost never a token candidate. Unknown
19|//   categories take the neutral 0.25. No protocol name is ever special-cased: one function scores
20|//   every row, and the page recomputes each number from the same constants.
21|//
22|// The 40 watchlist protocols (TVL >= floor_usd, no token, not a wrapped/staked product of one that
23|// trades) are the floor; the board then fills with pre-token protocols below the floor ranked by a
24|// radar score — tvl x growth x young-protocol urgency — until it holds at least 120 rows.
25|
26|/** The snapshot's protocol entry: exactly the ten fields the sealed input carries. */
27|export interface SnapshotProtocol {
28|  slug: string;
29|  name: string;
30|  category: string | null;
31|  chains: string[];
32|  tvl_usd: number;
33|  change_7d: number | null;
34|  mcap_usd: number | null;
35|  listed_at: string | null;
36|  gecko_id: string | null;
37|  symbol: string | null;
38|}
39|
40|/** The whole snapshot document. */
41|export interface Snapshot {
42|  as_of: string;
43|  source: string;
44|  floor_usd: number;
45|  protocols: SnapshotProtocol[];
46|  watchlist: string[];
47|}
48|
49|/** The model's constants, stated on the dashboard and shared by page and board. */
50|export interface ModelConstants {
51|  growth_weight: number;
52|  growth_floor: number;
53|  growth_cap: number;
54|  runway_floor: number;
55|  runway_range: number;
56|  runway_days: number;
57|  unknown_age_days: number;
58|  default_category_multiple: number;
59|}
60|
61|export const MODEL: ModelConstants = {
62|  growth_weight: 0.5,
63|  growth_floor: -60,
64|  growth_cap: 120,
65|  runway_floor: 0.8,
66|  runway_range: 0.4,
67|  runway_days: 1095,
68|  unknown_age_days: 365,
69|  default_category_multiple: 0.25,
70|};
71|
72|export const MODEL_VERSION = 'radar-2';
73|
74|/** What one dollar of TVL implies for a future token, by category. Stated on the dashboard. */
75|export const CATEGORY_MULTIPLES: Record<string, number> = {
76|  'cex': 0.05,
77|  'bridge': 0.18,
78|  'canonical bridge': 0.18,
79|  'liquid staking': 0.2,
80|  'liquid restaking': 0.22,
81|  'restaked btc': 0.2,
82|  'rwa': 0.24,
83|  'dex': 0.3,
84|  'yield': 0.28,
85|  'leveraged farm': 0.28,
86|  'liquidity manager': 0.28,
87|  'perpetuals': 0.32,
88|  'perp dex': 0.32,
89|  'derivatives': 0.32,
90|  'lending': 0.36,
91|  'cdp': 0.36,
92|  'collateralized debt': 0.36,
93|};
94|
95|/** A category's multiple: the exact key, else the first key it contains, else the neutral one. */
96|export function categoryMultiple(category: string | null, model: ModelConstants = MODEL): number {
97|  if (category === null) return model.default_category_multiple;
98|  const key = category.trim().toLowerCase();
99|  if (CATEGORY_MULTIPLES[key] !== undefined) return CATEGORY_MULTIPLES[key]!;
100|  for (const k of Object.keys(CATEGORY_MULTIPLES)) {
101|    if (key.includes(k)) return CATEGORY_MULTIPLES[k]!;
102|  }
103|  return model.default_category_multiple;
104|}
105|
106|/** Minimum board rows: 40 watchlist slugs plus at least 60 early rows below the floor. */
107|export const MIN_ROWS = 120;
108|
109|/** A farm step: the action, what it costs, and how long it takes. */
110|export interface FarmStep {
111|  text: string;
112|  cost: string;
113|  time: string;
114|}
115|
116|/** One row of board.json: a ranked pre-token protocol. */
117|export interface BoardRow {
118|  rank: number;
119|  slug: string;
120|  name: string;
121|  category: string | null;
122|  chains: string[];
123|  tvl_usd: number;
124|  change_7d: number | null;
125|  mcap_usd: number | null;
126|  listed_at: string | null;
127|  gecko_id: string | null;
128|  symbol: string | null;
129|  token_status: 'pre-token';
130|  watchlist: boolean;
131|  age_days: number | null;
132|  implied_value_usd: number;
133|  model: {
134|    category_multiple: number;
135|    growth_pct: number;
136|    growth_multiplier: number;
137|    runway_multiplier: number;
138|    age_days: number | null;
139|  };
140|  farm_steps: string[];
141|}
142|
143|/** A live-token protocol: it already trades, so the market's own value is the fact shown. */
144|export interface LiveRow {
145|  slug: string;
146|  name: string;
147|  category: string | null;
148|  chains: string[];
149|  tvl_usd: number;
150|  mcap_usd: number | null;
151|  change_7d: number | null;
152|  ratio: number | null;
153|}
154|
155|/** The compact dataset the dashboard renders, written to data.js beside the page. */
156|export interface RadarData {
157|  as_of: string;
158|  source: string;
159|  floor_usd: number;
160|  model: ModelConstants;
161|  model_version: string;
162|  category_multiples: Record<string, number>;
163|  watchlist_size: number;
164|  board_size: number;
165|  early_size: number;
166|  live_size: number;
167|  rows: (BoardRow & { is_watchlist: boolean })[];
168|  live: LiveRow[];
169|}
170|
171|/** Why the snapshot is not one this model can score. */
172|export class SnapshotError extends Error {
173|  constructor(message: string) {
174|    super(message);
175|    this.name = 'SnapshotError';
176|  }
177|}
178|
179|const DAY_MS = 86_400_000;
180|
181|/** A finite number, else `fallback`. */
182|function finite(value: unknown, fallback: number): number {
183|  return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
184|}
185|
186|/** Whole days from `from` to `to`, clamped at zero; null when either date is absent or unreadable. */
187|export function ageDays(asOf: string, listedAt: string | null): number | null {
188|  if (listedAt === null) return null;
189|  const a = Date.parse(`${asOf}T00:00:00Z`);
190|  const b = Date.parse(`${listedAt}T00:00:00Z`);
191|  if (!Number.isFinite(a) || !Number.isFinite(b)) return null;
192|  return Math.max(0, Math.floor((a - b) / DAY_MS));
193|}
194|
195|/** The multipliers and the implied value one protocol gets under the model. */
196|export function impliedValue(
197|  protocol: SnapshotProtocol,
198|  asOf: string,
199|  model: ModelConstants = MODEL,
200|): { implied: number; catMult: number; growthPct: number; growthMult: number; runwayMult: number; age: number | null } {
201|  const age = ageDays(asOf, protocol.listed_at);
202|  const catMult = categoryMultiple(protocol.category, model);
203|  const rawGrowth = finite(protocol.change_7d, 0);
204|  const growthPct = Math.min(model.growth_cap, Math.max(model.growth_floor, rawGrowth));
205|  const growthMult = 1 + (growthPct / 100) * model.growth_weight;
206|  const ageForModel = age ?? model.unknown_age_days;
207|  const runwayMult = model.runway_floor + (Math.min(Math.max(ageForModel, 0), model.runway_days) / model.runway_days) * model.runway_range;
208|  const implied = Math.max(1, Math.round(protocol.tvl_usd * catMult * growthMult * runwayMult));
209|  return { implied, catMult, growthPct, growthMult, runwayMult, age };
210|}
211|
212|/** DefiLlama's version-marker rule: a name ending in a release is a pool of another protocol. */
213|const VERSIONED = /\s(V\d+(\.\d+)?|v\d+(\.\d+)?|\d+\.\d+)$/;
214|
215|/** Whether a protocol records no token at all. */
216|export function isPreToken(p: SnapshotProtocol): boolean {
217|  return p.mcap_usd === null && p.gecko_id === null && p.symbol === null;
218|}
219|
220|/** Whether a protocol is one the board may rank: pre-token, not an exchange, not a versioned pool. */
221|export function isRankable(p: SnapshotProtocol): boolean {
222|  return isPreToken(p) && p.category !== 'CEX' && !VERSIONED.test(p.name);
223|}
224|
225|/** The snapshot's protocol by slug. */
226|function bySlug(protocols: SnapshotProtocol[]): Map<string, SnapshotProtocol> {
227|  return new Map(protocols.map((p) => [p.slug, p]));
228|}
229|
230|const slugCmp = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);
231|
232|/**
233| * The ranked board: every rankable pre-token protocol, watchlist first as the floor, then the early
234| * radar below the floor ranked by radar score (tvl x growth x young-protocol urgency) until MIN_ROWS rows.
235| */
236|export function buildBoard(snapshot: Snapshot, model: ModelConstants = MODEL): BoardRow[] {
237|  const index = bySlug(snapshot.protocols);
238|  const chosen = new Map<string, SnapshotProtocol>();
239|  for (const slug of snapshot.watchlist) {
240|    const p = index.get(slug);
241|    if (p !== undefined && isRankable(p)) chosen.set(slug, p);
242|  }
243|  // The early radar: pre-token protocols below the watchlist floor, strongest radar score first.
244|  // Score = tvl x (1 + growth/100 clamped) x young-protocol urgency (newer protocols are scouted
245|  // sooner, so a young high-TVL protocol outranks an old one of equal TVL).
246|  const early = snapshot.protocols
247|    .filter((p) => !chosen.has(p.slug) && isRankable(p) && p.tvl_usd < snapshot.floor_usd)
248|    .map((p) => {
249|      const age = ageDays(snapshot.as_of, p.listed_at);
250|      const g = Math.min(120, Math.max(-60, finite(p.change_7d, 0)));
251|      const ageScore = age === null ? 0.5 : age < 180 ? 1.5 : age < 365 ? 1.2 : age < 730 ? 0.9 : 0.6;
252|      return { p, score: p.tvl_usd * (1 + g / 100) * ageScore };
253|    })
254|    .sort((a, b) => b.score - a.score || slugCmp(a.p.slug, b.p.slug))
255|    .map((e) => e.p);
256|  for (const p of early) {
257|    if (chosen.size >= MIN_ROWS) break;
258|    chosen.set(p.slug, p);
259|  }
260|
261|  const scored = [...chosen.values()].map((p) => ({ p, ...impliedValue(p, snapshot.as_of, model) }));
262|  scored.sort((a, b) => b.implied - a.implied || b.p.tvl_usd - a.p.tvl_usd || slugCmp(a.p.slug, b.p.slug));
263|  return scored.map((s, i) => {
264|    const onList = snapshot.watchlist.includes(s.p.slug);
265|    return {
266|      rank: i + 1,
267|      slug: s.p.slug,
268|      name: s.p.name,
269|      category: s.p.category,
270|      chains: s.p.chains,
271|      tvl_usd: s.p.tvl_usd,
272|      change_7d: s.p.change_7d,
273|      mcap_usd: s.p.mcap_usd,
274|      listed_at: s.p.listed_at,
275|      gecko_id: s.p.gecko_id,
276|      symbol: s.p.symbol,
277|      token_status: 'pre-token' as const,
278|      watchlist: onList,
279|      age_days: s.age,
280|      implied_value_usd: s.implied,
281|      model: {
282|        category_multiple: s.catMult,
283|        growth_pct: s.growthPct,
284|        growth_multiplier: round4(s.growthMult),
285|        runway_multiplier: round4(s.runwayMult),
286|        age_days: s.age,
287|      },
288|      farm_steps: farmSteps(s.p, s.age).map(stepText),
289|    };
290|  });
291|}
292|
293|const round4 = (n: number): number => Math.round(n * 1e4) / 1e4;
294|
295|/** A step as one string: its action, then its cost and its time, within the gate's 20..600 characters. */
296|export function stepText(step: FarmStep): string {
297|  let s = `${step.text} Cost: ${step.cost}. Time: ${step.time}.`;
298|  if (s.length > 600) s = `${s.slice(0, 596)}...`;
299|  if (s.length < 20) s = `${s} Hold the position and check the protocol's own page.`;
300|  return s;
301|}
302|
303|/** The first chain a protocol names, or a neutral phrase. */
304|function chainOf(p: SnapshotProtocol): string {
305|  return p.chains.length > 0 ? p.chains[0]! : 'its main chain';
306|}
307|
308|/** How much capital one farm position needs, from the protocol's own TVL. */
309|function capitalFor(p: SnapshotProtocol): number {
310|  if (p.tvl_usd >= 5_000_000_000) return 250;
311|  if (p.tvl_usd >= 1_000_000_000) return 150;
312|  if (p.tvl_usd >= 100_000_000) return 100;
313|  return 50;
314|}
315|
316|/** How long to hold, from the protocol's age: younger protocols get a longer qualifying window. */
317|function holdDaysFor(age: number | null): number {
318|  if (age === null) return 30;
319|  if (age < 180) return 60;
320|  if (age < 365) return 45;
321|  return 30;
322|}
323|
324|/** The category's core action, in words a farmer can follow. */
325|function actionFor(p: SnapshotProtocol, capital: number, chain: string): string {
326|  const c = (p.category ?? '').toLowerCase();
327|  const name = p.name;
328|  if (c.includes('lend') || c.includes('cdp') || c.includes('collateral')) return `Supply $${capital} of USDC to ${name} on ${chain} as lending collateral and keep the position open.`;
329|  if (c.includes('dex') || c.includes('yield') || c.includes('leveraged farm') || c.includes('liquidity')) return `Provide $${capital} of liquidity to ${name}'s deepest pool on ${chain} and keep the LP position open.`;
330|  if (c.includes('perpetual') || c.includes('derivative')) return `Deposit $${capital} of USDC as margin on ${name} and open one small, hedged position.`;
331|  if (c.includes('bridge')) return `Bridge $${capital} of USDC to ${chain} through ${name} and use the bridged funds inside its app.`;
332|  if (c.includes('staking') || c.includes('restak')) return `Stake $${capital} of the chain's staking asset through ${name} and keep the receipt token.`;
333|  if (c.includes('prediction')) return `Fund $${capital} on ${name} and place one small position on its main market.`;
334|  if (c.includes('curator') || c.includes('allocator') || c.includes('vault')) return `Deposit $${capital} into a ${name} vault on ${chain} and keep the vault shares.`;
335|  if (c.includes('stable')) return `Mint or deposit $${capital} of the stable asset through ${name} on ${chain} and hold it.`;
336|  if (c.includes('rwa')) return `Mint $${capital} of the protocol's yield-bearing asset on ${chain} and hold it in the same wallet.`;
337|  if (c.includes('insurance')) return `Buy $${capital} of cover from ${name} on ${chain} and keep the policy in your wallet.`;
338|  if (c.includes('launch') || c.includes('incubat')) return `Join ${name}'s public track on ${chain} with $${capital} and complete every quest it lists.`;
339|  return `Deposit $${capital} of USDC into ${name} on ${chain} and keep the position open.`;
340|}
341|
342|/**
343| * A protocol's farm plan: seven steps, each an action with a cost and a time. The plan is derived
344| * from the protocol's own record (category, chains, TVL, age), never from a hand-written list of names.
345| */
346|export function farmSteps(p: SnapshotProtocol, age: number | null): FarmStep[] {
347|  const chain = chainOf(p);
348|  const capital = capitalFor(p);
349|  const hold = holdDaysFor(age);
350|  const alt = p.chains.length > 1 ? p.chains[1]! : chain;
351|  return [
352|    {
353|      text: `Set up a fresh wallet used only for farming ${p.name}, and keep its seed phrase offline.`,
354|      cost: 'under $3 of gas for the first transaction',
355|      time: '5 minutes',
356|    },
357|    {
358|      text: `Fund it on ${chain} with $${capital} of USDC or the chain's gas asset from an exchange or a bridge you already use.`,
359|      cost: `$${capital} of capital plus any bridge or withdrawal fee`,
360|      time: '10 minutes',
361|    },
362|    {
363|      text: `${actionFor(p, capital, chain)}`,
364|      cost: `$${capital} of capital and about $${capital >= 150 ? 8 : 4} of gas`,
365|      time: '15 minutes to set up',
366|    },
367|    {
368|      text: `Make one qualifying action each week — a deposit, a swap, a borrow-repay or a vote — alternating between ${chain} and ${alt} where the protocol runs on both.`,
369|      cost: 'about $2 of gas a week',
370|      time: '10 minutes a week',
371|    },
372|    {
373|      text: `Hold the position for at least ${hold} days so the activity lands in more than one snapshot, and record every transaction hash in a farm log.`,
374|      cost: `the $${capital} stays in the position`,
375|      time: `${hold} days`,
376|    },
377|    {
378|      text: `Watch ${p.name}'s own announcements for a points program or an incentives season, and join it early rather than late.`,
379|      cost: 'no fee beyond gas',
380|      time: '5 minutes a week',
381|    },
382|    {
383|      text: `Before you withdraw, claim rewards only from the protocol's own page, then unwind slowly and log the exit prices.`,
384|      cost: 'a few dollars of gas to exit',
385|      time: '15 minutes',
386|    },
387|  ];
388|}
389|
390|/** The live-token protocols, by market cap, for the dashboard's Live token view. */
391|export function liveRows(snapshot: Snapshot): LiveRow[] {
392|  return snapshot.protocols
393|    .filter((p) => !isPreToken(p) && p.category !== 'CEX')
394|    .sort((a, b) => (b.mcap_usd ?? 0) - (a.mcap_usd ?? 0) || b.tvl_usd - a.tvl_usd)
395|    .slice(0, 30)
396|    .map((p) => ({
397|      slug: p.slug,
398|      name: p.name,
399|      category: p.category,
400|      chains: p.chains,
401|      tvl_usd: p.tvl_usd,
402|      mcap_usd: p.mcap_usd,
403|      change_7d: p.change_7d,
404|      ratio: p.mcap_usd !== null && p.tvl_usd > 0 ? round4(p.mcap_usd / p.tvl_usd) : null,
405|    }));
406|}
407|
408|/** Everything the dashboard renders, from the snapshot. */
409|export function buildRadar(snapshot: Snapshot, model: ModelConstants = MODEL): { board: BoardRow[]; radar: RadarData } {
410|  const board = buildBoard(snapshot, model);
411|  const live = liveRows(snapshot);
412|  const early = board.filter((r) => !snapshot.watchlist.includes(r.slug)).length;
413|  const radar: RadarData = {
414|    as_of: snapshot.as_of,
415|    source: snapshot.source,
416|    floor_usd: snapshot.floor_usd,
417|    model,
418|    model_version: MODEL_VERSION,
419|    category_multiples: CATEGORY_MULTIPLES,
420|    watchlist_size: snapshot.watchlist.length,
421|    board_size: board.length,
422|    early_size: early,
423|    live_size: live.length,
424|    rows: board.map((r) => ({ ...r, is_watchlist: snapshot.watchlist.includes(r.slug) })),
425|    live,
426|  };
427|  return { board, radar };
428|}
429|
430|/** The snapshot out of a file's text, refused unless it is the shape the model scores. */
431|export function parseSnapshot(text: string): Snapshot {
432|  let raw: unknown;
433|  try {
434|    raw = JSON.parse(text);
435|  } catch {
436|    throw new SnapshotError('snapshot.json is not JSON');
437|  }
438|  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) throw new SnapshotError('snapshot.json is not a JSON object');
439|  const o = raw as Record<string, unknown>;
440|  if (typeof o.as_of !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(o.as_of)) throw new SnapshotError('snapshot.json has no as_of date');
441|  if (typeof o.source !== 'string') throw new SnapshotError('snapshot.json has no source');
442|  if (typeof o.floor_usd !== 'number' || !Number.isSafeInteger(o.floor_usd) || o.floor_usd <= 0) throw new SnapshotError('snapshot.json has no floor_usd');
443|  if (!Array.isArray(o.protocols)) throw new SnapshotError('snapshot.json has no protocols array');
444|  if (!Array.isArray(o.watchlist) || o.watchlist.some((s) => typeof s !== 'string')) throw new SnapshotError('snapshot.json has no watchlist of slugs');
445|  const protocols = o.protocols.map((v, i) => {
446|    if (typeof v !== 'object' || v === null || Array.isArray(v)) throw new SnapshotError(`snapshot.json's protocol ${i} is not an object`);
447|    const p = v as Record<string, unknown>;
448|    if (typeof p.slug !== 'string' || typeof p.name !== 'string' || typeof p.tvl_usd !== 'number' || !Number.isFinite(p.tvl_usd)) {
449|      throw new SnapshotError(`snapshot.json's protocol ${i} lacks a slug, a name or a TVL`);
450|    }
451|    return {
452|      slug: p.slug,
453|      name: p.name,
454|      category: typeof p.category === 'string' ? p.category : null,
455|      chains: Array.isArray(p.chains) ? p.chains.filter((c): c is string => typeof c === 'string') : [],
456|      tvl_usd: p.tvl_usd,
457|      change_7d: typeof p.change_7d === 'number' && Number.isFinite(p.change_7d) ? p.change_7d : null,
458|      mcap_usd: typeof p.mcap_usd === 'number' && Number.isFinite(p.mcap_usd) ? p.mcap_usd : null,
459|      listed_at: typeof p.listed_at === 'string' ? p.listed_at : null,
460|      gecko_id: typeof p.gecko_id === 'string' ? p.gecko_id : null,
461|      symbol: typeof p.symbol === 'string' ? p.symbol : null,
462|    };
463|  });
464|  return {
465|    as_of: o.as_of,
466|    source: o.source,
467|    floor_usd: o.floor_usd,
468|    protocols,
469|    watchlist: o.watchlist as string[],
470|  };
471|}
472|
473|/** Why a board is not one the gate will take, or null: coverage, ranks, order, and farm steps. */
474|export function boardIssue(board: BoardRow[], snapshot: Snapshot): string | null {
475|  const slugs = new Set(board.map((r) => r.slug));
476|  const missing = snapshot.watchlist.filter((s) => !slugs.has(s));
477|  if (missing.length > 0) return `the board misses ${missing.length} watchlist slug${missing.length === 1 ? '' : 's'}: ${missing.slice(0, 5).join(', ')}`;
478|  if (board.length < 100) return `the board holds ${board.length} rows, under the 100 the gate asks`;
479|  const ranks = board.map((r) => r.rank).sort((a, b) => a - b);
