29|/** --name <value> out of the arguments, or the fallback. */
30|function arg(name: string, fallback: string): string {
31|  const at = process.argv.indexOf(`--${name}`);
32|  if (at >= 0 && at + 1 < process.argv.length) return process.argv[at + 1]!;
33|  const withEquals = process.argv.find((a) => a.startsWith(`--${name}=`));
34|  return withEquals === undefined ? fallback : withEquals.slice(name.length + 3);
