58|/** Copy one directory's regular files into `to`, skipping names that start with a dot. */
59|function copyFiles(from: string, to: string): string[] {
60|  if (!existsSync(from)) return [];
61|  mkdirSync(to, { recursive: true });
62|  const copied: string[] = [];
63|  for (const name of readdirSync(from)) {
64|    if (name.startsWith('.')) continue;
